using CTXD.Server.Data;using Npgsql;
namespace CTXD.Server.Services;
public sealed record ChatSendRequest(string Type,string? To,string Message);
public sealed record ChatMessageView(long Id,string Type,long FromId,string From,string? To,string Message,DateTimeOffset CreatedAt);
public sealed record BlacklistView(long Id,long PlayerId,string Name);
public sealed class ChatService(GameDb db,GamePushHub push)
{
 public async Task<ChatMessageView> SendAsync(long sender,string type,string? to,string text,CancellationToken ct){type=type.ToUpperInvariant();text=(text??"").Trim();if(text.Length is 0 or>150)throw new GameException("CHAT_LENGTH_INVALID","Legacy chat messages must contain 1-150 characters.");if(type=="GLOBAL"||type=="LEGION")return new(0,type,sender,"",to,text,DateTimeOffset.UtcNow);if(type is not("COUNTRY" or "ONE2ONE"))throw new GameException("CHAT_TYPE_INVALID","Unsupported legacy chat channel.");await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);string from;short force;await using(var p=new NpgsqlCommand("SELECT display_name,force_id FROM players WHERE id=$1",c,t)){p.Parameters.AddWithValue(sender);await using var r=await p.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("PLAYER_NOT_FOUND","Player does not exist.",404);from=r.IsDBNull(0)?"":r.GetString(0);force=r.GetInt16(1);}long? recipient=null;if(type=="ONE2ONE"){await using var p=new NpgsqlCommand("SELECT id,force_id FROM players WHERE display_name=$1",c,t);p.Parameters.AddWithValue(to??"");await using var r=await p.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("CHAT_PLAYER_NOT_FOUND","Chat recipient does not exist.",404);recipient=r.GetInt64(0);if(recipient==sender)throw new GameException("CHAT_SELF_FORBIDDEN","Cannot chat with yourself.");if(r.GetInt16(1)!=force)throw new GameException("CHAT_CROSS_FORCE_FORBIDDEN","Legacy private chat cannot cross nations.");}await using(var repeated=new NpgsqlCommand("SELECT count(*) FROM (SELECT message FROM chat_messages WHERE sender_player_id=$1 AND created_at>now()-interval '10 minutes' ORDER BY created_at DESC LIMIT 10) x WHERE message=$2",c,t)){repeated.Parameters.AddWithValue(sender);repeated.Parameters.AddWithValue(text);if(Convert.ToInt32(await repeated.ExecuteScalarAsync(ct))>=3)throw new GameException("CHAT_CONTENT_REPEATED","Chat content repeated too many times.");}long id;var now=DateTimeOffset.UtcNow;await using(var save=new NpgsqlCommand("INSERT INTO chat_messages(sender_player_id,recipient_player_id,force_id,channel,message,created_at) VALUES($1,$2,$3,$4,$5,$6) RETURNING id",c,t)){save.Parameters.AddWithValue(sender);save.Parameters.AddWithValue(recipient is null?DBNull.Value:(object)recipient.Value);save.Parameters.AddWithValue(type=="COUNTRY"?(object)force:DBNull.Value);save.Parameters.AddWithValue(type);save.Parameters.AddWithValue(text);save.Parameters.AddWithValue(now);id=Convert.ToInt64(await save.ExecuteScalarAsync(ct));}await t.CommitAsync(ct);var view=new ChatMessageView(id,type,sender,from,to,text,now);if(recipient.HasValue){if(!await BlocksAsync(recipient.Value,sender,ct))await push.SendAsync(recipient.Value,"chat.message",view,ct);await push.SendAsync(sender,"chat.message",view,ct);}else{await using var readers=await db.DataSource.OpenConnectionAsync(ct);await using var q=new NpgsqlCommand("SELECT id FROM players WHERE force_id=$1",readers);q.Parameters.AddWithValue(force);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct)){var target=r.GetInt64(0);if(!await BlocksAsync(target,sender,ct))await push.SendAsync(target,"chat.message",view,ct);}}return view;}
 public async Task<ChatMessageView[]> HistoryAsync(long player,string type,CancellationToken ct){type=type.ToUpperInvariant();await using var c=await db.DataSource.OpenConnectionAsync(ct);var rows=new List<ChatMessageView>();var sql=type=="COUNTRY"?"SELECT m.id,m.channel,m.sender_player_id,p.display_name,NULL,m.message,m.created_at FROM chat_messages m JOIN players p ON p.id=m.sender_player_id JOIN players me ON me.id=$1 WHERE m.channel='COUNTRY' AND m.force_id=me.force_id AND NOT EXISTS(SELECT 1 FROM player_blacklist b WHERE b.player_id=$1 AND b.blocked_player_id=m.sender_player_id) ORDER BY m.created_at DESC LIMIT 50":"SELECT m.id,m.channel,m.sender_player_id,p.display_name,t.display_name,m.message,m.created_at FROM chat_messages m JOIN players p ON p.id=m.sender_player_id LEFT JOIN players t ON t.id=m.recipient_player_id WHERE m.channel='ONE2ONE' AND (m.sender_player_id=$1 OR m.recipient_player_id=$1) AND NOT EXISTS(SELECT 1 FROM player_blacklist b WHERE b.player_id=$1 AND b.blocked_player_id=m.sender_player_id) ORDER BY m.created_at DESC LIMIT 50";await using var cmd=new NpgsqlCommand(sql,c);cmd.Parameters.AddWithValue(player);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add(new(r.GetInt64(0),r.GetString(1),r.GetInt64(2),r.IsDBNull(3)?"":r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.GetString(5),r.GetFieldValue<DateTimeOffset>(6)));return rows.ToArray();}
 public async Task<BlacklistView[]> BlacklistAsync(long player,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);var rows=new List<BlacklistView>();await using var cmd=new NpgsqlCommand("SELECT b.id,p.id,p.display_name FROM player_blacklist b JOIN players p ON p.id=b.blocked_player_id WHERE b.player_id=$1 ORDER BY b.id",c);cmd.Parameters.AddWithValue(player);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add(new(r.GetInt64(0),r.GetInt64(1),r.IsDBNull(2)?"":r.GetString(2)));return rows.ToArray();}
 public async Task AddBlockAsync(long player,string name,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand("INSERT INTO player_blacklist(player_id,blocked_player_id) SELECT $1,id FROM players WHERE display_name=$2 AND id<>$1 ON CONFLICT DO NOTHING",c);cmd.Parameters.AddWithValue(player);cmd.Parameters.AddWithValue(name);if(await cmd.ExecuteNonQueryAsync(ct)==0){await using var exists=new NpgsqlCommand("SELECT 1 FROM players WHERE display_name=$1",c);exists.Parameters.AddWithValue(name);if(await exists.ExecuteScalarAsync(ct)is null)throw new GameException("CHAT_PLAYER_NOT_FOUND","Player does not exist.",404);}}
 public async Task RemoveBlockAsync(long player,long id,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand("DELETE FROM player_blacklist WHERE id=$1 AND player_id=$2",c);cmd.Parameters.AddWithValue(id);cmd.Parameters.AddWithValue(player);await cmd.ExecuteNonQueryAsync(ct);}
 async Task<bool> BlocksAsync(long player,long sender,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var cmd=new NpgsqlCommand("SELECT 1 FROM player_blacklist WHERE player_id=$1 AND blocked_player_id=$2",c);cmd.Parameters.AddWithValue(player);cmd.Parameters.AddWithValue(sender);return await cmd.ExecuteScalarAsync(ct)is not null;}
}
